def median(values):
    if not values:
        raise ValueError("Cannot calculate median of an empty list")

    ordered = sorted(values)
    n = len(ordered)

    if n % 2 == 1:
        # Odd number of items: return the middle value
        return ordered[n // 2]
    else:
        # Even number of items: return the mean of the two middle values
        middle1 = ordered[n // 2 - 1]
        middle2 = ordered[n // 2]
        return (middle1 + middle2) / 2

